head.script:
scwin.showData = function() {
    alert("wframe_SKT-261_(WSQ-916)_main");
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행하고 개발자모드(F12)를 실행한다.
    //1. Run the sample file and run developer mode (F12).
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. 콘솔로그에 scwin Runtime ID = wfm2_sub1_scwin 와 parent.scwin Runtime ID = scwin값이 정상적으로 보여진다.(이전에는 값이 넘어오지 않음)
    //1. The scwin Runtime ID = wfm2_sub1_scwin and parent.scwin Runtime ID = scwin values ​​are displayed normally in the console log.
    WebSquare.wUnit.addCommand("assert", "window.logMessage1 == 'parent.ibx_id Runtime Id : '+$p.id+'ibx_id'", "true");
    WebSquare.wUnit.addCommand("assert", "window.logMessage2 == 'ibx_name Runtime Id : '+$p.id+'wfm2_sub1_ibx_name'", "true");
    WebSquare.wUnit.addCommand("assert", "window.logMessage3 == 'scwin Runtime Id : '+$p.id+'wfm2_sub1_scwin'", "true");
    WebSquare.wUnit.addCommand("assert", "window.logMessage4 == 'parent.scwin Runtime Id : '+$p.id+'scwin'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 28-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
